def is_1122_string(s: str) -> bool:
    n = len(s)
    if n % 2 != 0:
        return False

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    if any(count != 0 and count != 2 for count in counts.values()):
        return False

    for i in range(1, n // 2 + 1):
        if s[2 * i - 1] != s[2 * i]:
            return False

    return True

