class Solution:
    def duplicateNumbersXOR(self, nums: List[int]) -> int:
        count = {}
        for num in nums:
            count[num] = count.get(num, 0) + 1

        result = 0
        for num in count:
            if count[num] == 2:
                result ^= num
        return result
