import sys

def solve():
    # Read N and M
    try:
        line1 = sys.stdin.read().split()
    except Exception:
        return

    if not line1:
        return

    N = int(line1[0])
    M = int(line1[1])

    A = []
    for i in range(N):
        A.append(int(line1[2 + i]))

    B = []
    for i in range(M):
        B.append(int(line1[2 + i + 1]))

    # Process each sushi
    results = []
    for i in range(M):
        sushi_b = B[i]
        person = -1
        # Check each person in order
        for j in range(1, N + 1):
            if B[i] >= A[j-1]:
                person = j
                break
        results.append(str(person))
    print('\n'.join(results))

if __name__ == '__main__':
    solve()
