class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        max_sum = -float('inf')

        for length in range(1, n // k + 1):
            if length % k == 0:
                current_sum = 0
                current_max = 0
                for i in range(n):
                    current_sum += nums[i]
                    if current_sum > current_max:
                        current_max = current_sum
                if current_max > max_sum:
                    max_sum = current_max

